function JobGrid({jobs,onDetails=()=>{},onApply=()=>{},applied=new Set()}){return <div className="job-grid">{jobs.map(j=><article className="job-card" key={j.id}><div className="job-card-top"><span className="company-mark large-mark">{j.companyName?.slice(0,1)||'C'}</span><span className="job-type">{j.employmentType||'Full-time'}</span></div><div className="job-company">{j.companyName}</div><h3>{j.title}</h3><div className="job-meta"><span><MapPin size={14}/>{j.location||'Location flexible'}</span><span><Clock3 size={14}/>{j.deadline?`Apply by ${new Date(j.deadline).toLocaleDateString('en-IN',{day:'numeric',month:'short'})}`:'Applications open'}</span></div>{j.salary&&<div className="job-salary">{j.salary}<small> package</small></div>}<div className="job-skills">{(j.skills||'Open to learn').split(',').slice(0,3).map((s,i)=><span key={i}>{s.trim()}</span>)}</div><div className="job-card-actions"><button className="button button-outline" onClick={()=>onDetails(j)}>Details</button><button disabled={applied.has(j.id)} className="button button-primary" onClick={()=>onApply(j)}>{applied.has(j.id)?'Applied':'Apply now'} {applied.has(j.id)?<Check size={15}/>:<ArrowRight size={15}/>}</button></div></article>)}</div>}
function JobModal({job,onClose,onApply,applied}){return <div className="modal-backdrop" onClick={onClose}><div className="modal job-modal" onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={onClose}><X/></button><div className="job-modal-head"><span className="company-mark large-mark">{job.companyName?.slice(0,1)}</span><div><div className="job-company">{job.companyName}</div><h2>{job.title}</h2></div></div><div className="job-meta modal-meta"><span><MapPin size={15}/>{job.location||'Location flexible'}</span><span><BriefcaseBusiness size={15}/>{job.employmentType||'Full-time'}</span><span><Clock3 size={15}/>{job.deadline?`Apply by ${job.deadline}`:'Applications open'}</span></div>{job.salary&&<div className="detail-fact"><b>Compensation</b><span>{job.salary}</span></div>}{job.minCgpa&&<div className="detail-fact"><b>Minimum CGPA</b><span>{job.minCgpa}</span></div>}{job.departments&&<div className="detail-fact"><b>Eligible departments</b><span>{job.departments}</span></div>}<DetailBlock title="About the role" text={job.description}/><DetailBlock title="What you'll do" text={job.responsibilities}/><DetailBlock title="What we're looking for" text={job.qualifications}/><DetailBlock title="Skills" text={job.skills}/><DetailBlock title="Selection process" text={job.selectionProcess}/><DetailBlock title="Additional requirements" text={job.additionalRequirements}/><button className="button button-primary full-button" disabled={applied} onClick={()=>onApply(job)}>{applied?'Already applied':'Apply for this role'} <ArrowRight size={16}/></button></div></div>}
function DetailBlock({title,text}){return text?<div className="detail-block"><b>{title}</b><p>{text}</p></div>:null}
