function AdminStudents(){const {data:students,busy,error}=useLoad('/admin/students',[]),[query,setQuery]=useState(''),[selected,setSelected]=useState(null);const filtered=students.filter(s=>`${s.fullName} ${s.email} ${s.profile?.college||''} ${s.profile?.department||''}`.toLowerCase().includes(query.toLowerCase()));const show=async s=>{try{const {data}=await api.get(`/admin/students/${s.id}`);setSelected(data)}catch(e){window.alert(messageOf(e))}};const download=async id=>{try{const r=await api.get(`/admin/students/${id}/resume`,{responseType:'blob'});const url=URL.createObjectURL(r.data),a=document.createElement('a');a.href=url;a.download='student-resume.pdf';a.click();URL.revokeObjectURL(url)}catch(e){window.alert(messageOf(e))}};return <><PageHeading eyebrow="YOUR STUDENT COMMUNITY" title="Students" subtitle="Get to know the people preparing for their next step."/><div className="job-tools"><div className="search-box"><Search size={18}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search name, college or department"/></div><span className="results-label">{filtered.length} students</span></div>{error&&<Alert text={error}/>}<section className="panel table-panel">{busy?<div className="loading-inline"><div className="spinner"/>Loading students…</div>:filtered.length?<div className="student-list">{filtered.map(s=><div className="student-row" key={s.id}><span className="user-avatar">{s.fullName.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><div className="student-main"><b>{s.fullName}</b><small>{s.email}</small></div><div className="student-academic"><b>{s.profile?.college||'College not added'}</b><small>{[s.profile?.department,s.profile?.cgpa&&`CGPA ${s.profile.cgpa}`].filter(Boolean).join(' · ')||'Academic details pending'}</small></div><button className="button button-outline small-button" onClick={()=>show(s)}>View profile <ArrowRight size={14}/></button></div>)}</div>:<EmptyState icon={<Users/>} title="No students match that search" text="Try another name or department."/>}</section>{selected&&<div className="modal-backdrop" onClick={()=>setSelected(null)}><div className="modal student-modal" onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={()=>setSelected(null)}><X/></button><div className="student-modal-head"><span className="user-avatar">{selected.fullName.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><div><div className="auth-kicker">STUDENT PROFILE</div><h2>{selected.fullName}</h2><p>{selected.email}</p></div></div><div className="student-detail-grid">{Object.entries(selected.profile||{}).filter(([k,v])=>v&&['phone','college','department','degree','specialization','semester','graduationYear','cgpa','backlogs','skills','programmingLanguages','certifications','projects','internships','workExperience','linkedinUrl','githubUrl','portfolioUrl'].includes(k)).map(([k,v])=><div key={k}><small>{k.replace(/[A-Z]/g,' $&').toUpperCase()}</small><b>{String(v)}</b></div>)}</div>{selected.profile?.resumeFilename&&<button className="button button-primary full-button" onClick={()=>download(selected.id)}><FileText size={16}/> View / download {selected.profile.resumeFilename}</button>}</div></div>}</>}
function AdminApplications(){const {data,setData,busy,error}=useLoad('/admin/applications',[]),[query,setQuery]=useState('');const change=async(id,status)=>{try{const {data:updated}=await api.patch(`/admin/applications/${id}/status`,{status});setData(data.map(a=>a.id===id?updated:a))}catch(e){window.alert(messageOf(e))}};const filtered=data.filter(a=>`${a.job?.title} ${a.job?.companyName} ${a.student?.fullName} ${a.status}`.toLowerCase().includes(query.toLowerCase()));return <><PageHeading eyebrow="STUDENT PROGRESS" title="Applications" subtitle="Review applications and keep students informed."/><div className="job-tools"><div className="search-box"><Search size={18}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search company, role, student or status"/></div><span className="results-label">{filtered.length} applications</span></div>{error&&<Alert text={error}/>}<section className="panel applications-panel">{busy?<div className="loading-inline"><div className="spinner"/>Loading applications…</div>:filtered.length?<div className="mini-list">{filtered.map(a=><ApplicationRow key={a.id} a={a} admin onStatus={change}/>)}</div>:<EmptyState icon={<FileText/>} title="No applications to show" text="New applications will appear here as students find the right opportunity."/>}</section></>}
export default App;
